485	    /**
486	     * Builds the {@code membershipNumber} for a newly created owner, formatted
487	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
488	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
489	     */
490	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
491	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
492	    }
493	
494	    /**
495	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
496	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
497	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
498	     * it is a pure function of that pair, every owner in the same household - whether created first
499	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
500	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
501	     * segment.
502	     */
503	    private static String householdIdFor(String lastName, String postcode) {
504	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
505	        try {
506	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
507	            StringBuilder sb = new StringBuilder(12);
508	            for (byte b : digest) {
509	                if (sb.length() >= 12) {
510	                    break;
511	                }
512	                sb.append(String.format("%02x", b));
513	            }
514	            return sb.substring(0, 12);
515	        } catch (NoSuchAlgorithmException ex) {
516	            throw new IllegalStateException("SHA-256 not available", ex);
517	        }
518	    }
519	
520	    /**
521	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
522	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
523	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
524	     */
525	    private int countNamesakes(String firstName, String lastName) {
526	        int count = 0;
527	        for (Owner existing : this.clinicService.findAllOwners()) {
528	            if (firstName.equalsIgnoreCase(existing.getFirstName())
529	                && lastName.equalsIgnoreCase(existing.getLastName())) {
530	                count++;
531	            }
532	        }
533	        return count;
534	    }
535	
536	    /**
537	     * Counts the members of the household the new owner will belong to, as it stands after this
538	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
539	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
540	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
541	     * stored on the owner as its {@code householdMemberCount}.
542	     */
543	    private int countHouseholdMembers(String householdId) {
544	        int count = 1;
545	        for (Owner existing : this.clinicService.findAllOwners()) {
546	            if (householdId.equals(existing.getHouseholdId())) {
547	                count++;
548	            }
549	        }
550	        return count;
551	    }
552	
553	    /**
554	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
555	     * that is not a hard identity collision but shares the new owner's {@code lastName} (compared
556	     * case-insensitively) and {@code postcode} while carrying a different normalized telephone. The
557	     * new owner's postcode must be present for a soft match to be possible. When several existing
558	     * owners qualify the one with the lowest id is chosen. Returns the matching owner's id, or
559	     * {@code null} when there is no soft match. This is evaluated after the hard-duplicate check has
560	     * already passed, so any owner sharing the lastName and postcode necessarily differs in telephone.
561	     *
562	     * <p>Because the household is now keyed on {@code (lastName, postcode)} - exactly the soft-match
563	     * key - a co-member reached here can only be one the caller declared via {@code sharesHousehold}
564	     * (otherwise the hard household-duplicate check would already have rejected it). A declared
565	     * household member is not a suspected duplicate, so no soft match is reported in that case.
566	     */
567	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone) {
568	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
569	            return null;
570	        }
571	        String postcode = ownerFieldsDto.getPostcode();
572	        if (postcode == null) {
573	            return null;
574	        }
575	        String lastName = ownerFieldsDto.getLastName();
576	        Integer matchId = null;
577	        for (Owner existing : this.clinicService.findAllOwners()) {
578	            if (existing.isDeleted()) {
579	                continue;
580	            }
581	            if (lastName == null || !lastName.equalsIgnoreCase(existing.getLastName())) {
582	                continue;
583	            }
584	            if (!postcode.equals(existing.getPostcode())) {
585	                continue;
586	            }
587	            String existingTelephone;
588	            try {
589	                existingTelephone = normalizeTelephone(existing.getTelephone());
590	            } catch (InvalidTelephoneException ex) {
591	                existingTelephone = null;
592	            }
593	            if (normalizedTelephone.equals(existingTelephone)) {
594	                continue;
595	            }
596	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
597	                matchId = existing.getId();
598	            }
599	        }
600	        return matchId;
601	    }
