603	    /**
604	     * The tenure, in days, that an owner must exceed before its tenure contributes membership
605	     * points. Tenure is measured from the owner's {@code registrationDate}, so a newly created owner
606	     * (whose tenure is zero) never satisfies this and thus never earns the tenure points on create.
607	     */
608	    private static final int TENURE_POINTS_THRESHOLD_DAYS = 365;
609	
610	    /**
611	     * The household size (number of members) at or above which an owner earns the household points.
612	     */
613	    private static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
614	
615	    /**
616	     * Computes the {@code membershipPoints} for an owner. Points start at 0, gain 2 when an email is
617	     * present, gain 1 when the owner's {@code namesakeCount} is 0, gain 2 when the owner's household
618	     * has {@value #HOUSEHOLD_POINTS_THRESHOLD} or more members, and gain 3 when the owner's tenure
619	     * (days elapsed since its {@code registrationDate}) exceeds {@value #TENURE_POINTS_THRESHOLD_DAYS}
620	     * days. Because a newly created owner has zero tenure, the tenure points never apply on create.
621	     * Evaluated after the owner's email, namesakeCount, householdMemberCount and registrationDate
622	     * have been set.
623	     */
624	    private static int membershipPointsFor(Owner owner) {
625	        int points = 0;
626	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
627	            points += 2;
628	        }
629	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
630	            points += 1;
631	        }
632	        if (owner.getHouseholdMemberCount() != null
633	            && owner.getHouseholdMemberCount() >= HOUSEHOLD_POINTS_THRESHOLD) {
634	            points += 2;
635	        }
636	        if (tenureInDays(owner) > TENURE_POINTS_THRESHOLD_DAYS) {
637	            points += 3;
638	        }
639	        return points;
640	    }
