642	    /**
643	     * Maps {@code membershipPoints} to the numeric {@code membershipLevel}: level 1 for 0-1 points,
644	     * 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
645	     */
646	    private static int membershipLevelForPoints(int points) {
647	        if (points <= 1) {
648	            return 1;
649	        }
650	        if (points <= 3) {
651	            return 2;
652	        }
653	        if (points <= 5) {
654	            return 3;
655	        }
656	        return 4;
657	    }
