659	    /**
660	     * The owner's tenure in whole days: the number of days elapsed from its {@code registrationDate}
661	     * up to the current server date. An owner with no registration date, or one dated in the future,
662	     * has a tenure of zero.
663	     */
664	    private static long tenureInDays(Owner owner) {
665	        LocalDate registrationDate = owner.getRegistrationDate();
666	        if (registrationDate == null) {
667	            return 0;
668	        }
669	        return Math.max(0, ChronoUnit.DAYS.between(registrationDate, LocalDate.now()));
670	    }
