687	        for (Owner existing : this.clinicService.findAllOwners()) {
688	            if (city.equalsIgnoreCase(existing.getCity())) {
689	                count++;
690	            }
691	        }
692	        if (count >= CITY_CAPACITY) {
693	            throw new CityAtCapacityException(city);
694	        }
695	    }
